    def _normalize_block_hash(
        self,
        block_hash: Union[str, bytes],
    ) -> bytes:
        """将 block hash 规范化为 bytes 类型"""
        # 安全处理 str 和 bytes 两种类型
        if isinstance(block_hash, str):
            try:
                h = bytes.fromhex(block_hash) if len(block_hash) == 64 \
                    else block_hash.encode("utf-8")
            except ValueError:
                h = block_hash.encode("utf-8")
        else:
            h = bytes(block_hash)
        return h

